import{_ as i,l as r,o as a,c as d,v as t,p as l,x as n,d as s,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"双端优先队列","description":"","frontmatter":{"title":"双端优先队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/double-ended-pq.md","filePath":"cs/double-ended-pq.md","lastUpdated":1789023840000}'),c={name:"cs/double-ended-pq.md"};function h(u,e,_,x,E,P){const o=r("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="双端优先队列" tabindex="-1">双端优先队列 <a class="header-anchor" href="#双端优先队列" aria-label="Permalink to &quot;双端优先队列&quot;">​</a></h1><div class="epigraph"><p>既要 $O(\\log n)$ 抽最小，也要 $O(\\log n)$ 抽最大；一个堆序不够，除非成对放置或两堆互指。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 3；Sedgewick and Wayne；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/mergeable-heap">上一课</a>的堆合同围绕同一端极值。<a href="/cs/deque">双端队列</a> 两端是位置不是键序。本课不 meld。缺口是双端优先队列（DEPQ）：<code>insert</code>、<code>get-min</code>/<code>delete-min</code>、<code>get-max</code>/<code>delete-max</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个独立堆（一个 min 一个 max）各插一份，删除时要同步删另一边，需要句柄或懒删。间隔堆（interval heap）：完全树每个节点存一对 \\((a,b)\\)，\\(a\\le b\\)，左端形成 min-heap 序、右端 max-heap 序。或 min-max 堆：偶数层 min、奇数层 max。缺口是<strong>在一份存储里同时维持两种堆序</strong>，避免 \\(2n\\) 全量复制。</p><p><span class="marginnote">Knuth 卷 3 讨论优先队列变体。教材中 interval heap 与 min-max heap 是常见两种表示。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>insert：放入末叶再沿 min 或 max 路径上滤，视新键与所在对/层的关系。delete-min：与普通堆类似，空洞从根补，但要同时修复另一端序。实现细节因表示而异，合同统一为两端对数。</p>',8)),(a(),l(p,null,{default:n(()=>[m(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22insert%22%5D%20--%3E%20DEPQ%5B%22%E5%8F%8C%E7%AB%AF%E4%BC%98%E5%85%88%E9%98%9F%E5%88%97%22%5D%0A%20%20DEPQ%20--%3E%20MIN%5B%22delete-min%22%5D%0A%20%20DEPQ%20--%3E%20MAX%5B%22delete-max%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与有序 BST：顺序统计树也能删最小最大（最左最右），还能 rank；DEPQ 不支持任意键查找，常数按堆。选结构看操作集。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不能只用一个 min-heap 另存当前 max 变量：删 max 后 max 未知，除非扫。成对或分层把「另一端候选」永远放在堆路径上。空间 \\(\\Theta(n)\\)。</p><p>不要与 deque 的「两端下标」混淆：DEPQ 的两端是键的极值。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把无锁 DEPQ 写完。整数键、宇宙 \\([0,U)\\) 上找后继，堆帮不上忙——那是 van Emde Boas 的 \\(O(\\log\\log U)\\)，下一课换模型。</p><p>后课默认：两端极值用 DEPQ 或有序树。有界整数宇宙上的前驱后继，用 vEB。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DEPQ：min 与 max 都对数，不是位置 deque。</li><li>表示：interval heap、min-max 堆、或双堆加句柄。</li><li>整数宇宙前驱后继交给 vEB。</li><li>出处：Knuth 卷 3；Sedgewick and Wayne；Cormen et al.。</li></ul>',9))])}const q=i(c,[["render",h]]);export{b as __pageData,q as default};
